package transpile

import (
	"strings"
	"testing"
)

func TestQBECoreSyntax(t *testing.T) {
	got, err := QBE(`
let add = fn(a, b) { return a + b }
let value = add(1, 2)
`, "test.doml")
	if err != nil {
		t.Fatal(err)
	}
	for _, want := range []string{
		"# Generated by domscript -T qbe",
		"function w $add(w %a, w %b)",
		"%bin1 =w add %a, %b",
		"export function w $main()",
		"call $add(w 1, w 2)",
	} {
		if !strings.Contains(got, want) {
			t.Errorf("output missing %q:\n%s", want, got)
		}
	}
}

func TestQBERejectsInvalidSource(t *testing.T) {
	if _, err := QBE("let =", "test.doml"); err == nil {
		t.Fatal("expected syntax error")
	}
}
